{"explanation":"A Riemann sum approximates the area under a curve by slicing the region into n thin rectangles and adding up their areas, each with width Δx = 2/n and height f(xᵢ) = xᵢ² at a chosen sample point. Since x² is increasing, right endpoints overestimate the area while left endpoints underestimate it — and the true value ∫₀² x² dx = 8/3 ≈ 2.667 is trapped between them. Drag the slider to increase n and watch the sum converge to 8/3 as the error shrinks toward zero. Use the checkbox to switch between right and left endpoints to see the over- vs. under-estimation.","manimCode":"const f = (x) => x * x;
const EXACT = 8 / 3;
let n = 8;
let useRight = true;

const ax = new Axes({
  xRange: [-0.5, 2.5, 0.5],
  yRange: [-0.5, 4.5, 1],
  xLength: 7.5,
  yLength: 6,
  tips: true
});
ax.moveTo([-1.8, -0.3, 0]);
const axisLabels = ax.getAxisLabels();
const curve = ax.plot(f, { color: YELLOW, xRange: [0, 2], strokeWidth: 4 });

function buildRects(count, right) {
  const rects = [];
  const dx = 2 / count;
  for (let i = 0; i < count; i++) {
    const xL = i * dx;
    const xR = (i + 1) * dx;
    const h = f(right ? xR : xL);
    const r = new Polygon({
      vertices: [ax.c2p(xL, 0), ax.c2p(xR, 0), ax.c2p(xR, h), ax.c2p(xL, h)],
      color: BLUE_B,
      strokeWidth: 1.5
    });
    r.setFill(BLUE, 0.35);
    rects.push(r);
  }
  return new VGroup(...rects);
}

function approxArea(count, right) {
  const dx = 2 / count;
  let s = 0;
  for (let i = 0; i < count; i++) {
    const x = right ? (i + 1) * dx : i * dx;
    s += f(x) * dx;
  }
  return s;
}

let rectGroup = buildRects(n, useRight);
let approxLabel = null;
let errorLabel = null;

function updateLabels() {
  const a = approxArea(n, useRight);
  const err = Math.abs(a - EXACT);
  if (approxLabel) scene.remove(approxLabel);
  if (errorLabel) scene.remove(errorLabel);
  approxLabel = new Text({ text: `Approx (n=${n}): ${a.toFixed(4)}`, color: BLUE_B, fontSize: 26 });
  errorLabel = new Text({ text: `Error: ${err.toFixed(4)}`, color: RED, fontSize: 26 });
  approxLabel.moveTo([4.0, 0.5, 0]);
  errorLabel.moveTo([4.0, -0.2, 0]);
  scene.add(approxLabel, errorLabel);
}

function refresh() {
  scene.remove(rectGroup);
  rectGroup = buildRects(n, useRight);
  scene.add(rectGroup);
  updateLabels();
}

const title = new Text({ text: 'Riemann Sums for y = x² on [0, 2]', color: WHITE, fontSize: 30 });
title.moveTo([-0.9, 3.4, 0]);

const exactTex = new MathTex({ latex: '\\int_0^2 x^2\\,dx = \\frac{8}{3} \\approx 2.6667' });
await exactTex.waitForRender();
exactTex.scale(0.7);
exactTex.moveTo([4.0, 1.4, 0]);

const curveLabel = new MathTex({ latex: 'y = x^2' });
await curveLabel.waitForRender();
curveLabel.scale(0.8);
curveLabel.setColor(YELLOW);
curveLabel.moveTo(ax.c2p(2.32, 4.15));

await scene.play(new Write(title));
scene.add(ax, axisLabels);
await scene.play(new Create(curve));
scene.add(rectGroup);
await scene.play(new FadeIn(rectGroup));
scene.add(exactTex, curveLabel);
updateLabels();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({
  label: 'Number of rectangles (n)',
  min: 1,
  max: 100,
  value: n,
  step: 1,
  onChange: (v) => { n = v; refresh(); }
});
controls.addCheckbox({
  label: 'Right endpoints (off = left)',
  checked: true,
  onChange: (c) => { useRight = c; refresh(); }
});

await scene.wait(999999);"}

